-- English Physics Chapter 7: Solid-State Electronics (72 supplied MCQs).
-- Keep question order, answer indices, and stable IDs in sync with
-- src/data/physicsChapter7EnglishMcqs.json, the frontend fallback.
WITH seed (id, section, question, choices, answer_index, sort_order) AS (
  VALUES
  ('c7e5d7e0-1b4a-4d99-a077-000000000001'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'What do all electronic devices depend on basically?', '["Crystal diodes and transistors","Vacuum tubes and magnetic coils","Electrolytic capacitors and transformers","Mechanical switches and relays"]'::jsonb, 0, 1),
  ('c7e5d7e0-1b4a-4d99-a077-000000000002'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'Which electrons participate in chemical reactions and determine the electronic properties of matter?', '["Core electrons in the innermost orbit","Valence electrons in the outer shell","Neutrons inside the atomic nucleus","Protons bound in the inner shells"]'::jsonb, 1, 2),
  ('c7e5d7e0-1b4a-4d99-a077-000000000003'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'Compared to electrons in inner shells close to the nucleus, valence electrons have:', '["Lower energy and stronger attractive force to the nucleus","Greater energy and minimum attractive force to the nucleus","Zero energy and no attraction to the nucleus","Equal energy and equal attraction regardless of shell"]'::jsonb, 1, 3),
  ('c7e5d7e0-1b4a-4d99-a077-000000000004'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'In a hydrogen atom, what is the meaning of the zero energy level (E = 0) and the lowest electron energy?', '["E = 0 is the lowest level; lowest energy is +13.6 eV","E = 0 is the highest level of atom energy; lowest energy is −13.6 eV","E = 0 is the ground state; lowest energy is 0 eV","E = 0 is the valence band edge; lowest energy is −1.1 eV"]'::jsonb, 1, 4),
  ('c7e5d7e0-1b4a-4d99-a077-000000000005'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'What happens when an electron in a single hydrogen atom at the ground state gains +13.6 eV of energy?', '["It falls into the nucleus","It shifts to the donor level","It escapes from the hydrogen atom","It forms an acceptor level"]'::jsonb, 2, 5),
  ('c7e5d7e0-1b4a-4d99-a077-000000000006'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'Which range represents the specific electrical resistance of conductors?', '["10¹⁰ to 10¹⁶ Ω·m","10⁻⁵ to 10⁸ Ω·m","10⁻⁸ to 10⁻⁵ Ω·m","10² to 10⁶ Ω·m"]'::jsonb, 2, 6),
  ('c7e5d7e0-1b4a-4d99-a077-000000000007'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'Which range represents the specific electrical resistance of insulators?', '["10¹⁰ to 10¹⁶ Ω·m","10⁻⁸ to 10⁻⁵ Ω·m","10⁻⁵ to 10⁻² Ω·m","10⁻¹² to 10⁻⁸ Ω·m"]'::jsonb, 0, 7),
  ('c7e5d7e0-1b4a-4d99-a077-000000000008'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'The specific electrical resistance of semiconductors lies around:', '["10¹² to 10¹⁸ Ω·m","10⁻⁵ to 10⁸ Ω·m","10⁻¹⁰ to 10⁻⁷ Ω·m","0 to 10⁻⁸ Ω·m"]'::jsonb, 1, 8),
  ('c7e5d7e0-1b4a-4d99-a077-000000000009'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'In solid materials made of massive numbers of atoms, why do energy levels divide into allowed secondary shells forming energy bands?', '["Because each atom is completely isolated with zero interaction","Because electrons of an atom are affected by electrons of neighboring atoms in the same material","Because the nucleus loses its positive charge","Because the forbidden energy gap disappears in all solids"]'::jsonb, 1, 9),
  ('c7e5d7e0-1b4a-4d99-a077-000000000010'::uuid, 'Atomic Shells, Energy Levels, Conductors, Insulators & Semiconductors', 'What is the forbidden energy gap?', '["A region of high allowed energy levels full of free electrons","The gap between valence band and conduction band that has no allowed energy levels and cannot be occupied by electrons","The overlapping region inside metals","The shell closest to the nucleus"]'::jsonb, 1, 10),
  ('c7e5d7e0-1b4a-4d99-a077-000000000011'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'To move from the valence band to the conduction band across the forbidden energy gap, an electron must gain energy from an outer source (thermal, light, or electric field) that is:', '["Strictly less than the forbidden energy gap","Not less than the amount of the forbidden energy gap","Equal to zero","Independent of the forbidden energy gap"]'::jsonb, 1, 11),
  ('c7e5d7e0-1b4a-4d99-a077-000000000012'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'Why do conductors (such as metals) have high electrical conductivity?', '["Their forbidden energy gap is about 5 eV","Valence bands overlap with conduction bands with no forbidden energy gap, so valence electrons move freely","Their conduction band is completely empty at all temperatures","Their valence electrons are bound with maximum force"]'::jsonb, 1, 12),
  ('c7e5d7e0-1b4a-4d99-a077-000000000013'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'Why does the electrical conductivity of a metal decrease when its temperature increases?', '["Because electron-hole pairs stop generating","Because its electrical resistance increases due to an increased time rate of vibrational energy of atoms and molecules","Because a wide forbidden energy gap opens up","Because free electrons become bound to the nucleus"]'::jsonb, 1, 13),
  ('c7e5d7e0-1b4a-4d99-a077-000000000014'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'Why does an insulator normally have no electrical conductivity?', '["Because its valence band is empty and conduction band is full","Because its forbidden energy gap is relatively wide (around 5 eV or more), preventing valence electrons from crossing when supplied energy is smaller","Because valence and conduction bands overlap","Because it has too many free electrons at room temperature"]'::jsonb, 1, 14),
  ('c7e5d7e0-1b4a-4d99-a077-000000000015'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'What happens when a huge electric field or heat is applied to an insulator?', '["Its forbidden energy gap increases to infinity","It may lead to collapse of the insulator and a very little current flows through it","It turns into a superconductor with zero resistance","Nothing happens under any condition"]'::jsonb, 1, 15),
  ('c7e5d7e0-1b4a-4d99-a077-000000000016'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'Under which conditions does an intrinsic semiconductor behave like an insulator?', '["At room temperature (300 K) under bright light","At very low temperature (0 K, absolute zero) and in the absence of light","When doped with high levels of antimony","When exposed to a strong electric field at 300 K"]'::jsonb, 1, 16),
  ('c7e5d7e0-1b4a-4d99-a077-000000000017'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'Which semiconductors are most commonly used in electronics applications?', '["Copper and gold","Germanium (Ge) and Silicon (Si)","Boron and aluminum","Silver and iron"]'::jsonb, 1, 17),
  ('c7e5d7e0-1b4a-4d99-a077-000000000018'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'At room temperature (300 K), what are the forbidden energy gap values for intrinsic silicon and intrinsic germanium?', '["0.72 eV for silicon and 1.1 eV for germanium","1.1 eV for intrinsic silicon and 0.72 eV for intrinsic germanium","5.0 eV for silicon and 1.1 eV for germanium","0.5 eV for silicon and 0.1 eV for germanium"]'::jsonb, 1, 18),
  ('c7e5d7e0-1b4a-4d99-a077-000000000019'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'When an intrinsic semiconductor is heated from 0 K to room temperature (300 K), why does its electrical conductivity increase?', '["Because its electrical resistance increases rapidly","Because valence electrons gain thermal energy to break covalent bonds, move to the conduction band, and increase electron-hole pair concentration","Because holes disappear completely","Because it becomes a pure metal"]'::jsonb, 1, 19),
  ('c7e5d7e0-1b4a-4d99-a077-000000000020'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'How is an electron-hole pair generated in a semiconductor?', '["When a free electron moves from the conduction band into the forbidden gap","When an electron moves from the valence band to the conduction band, leaving an empty space (hole) acting as a positive charge","When two holes combine in the conduction band","When donor atoms lose all valence electrons at 0 K"]'::jsonb, 1, 20),
  ('c7e5d7e0-1b4a-4d99-a077-000000000021'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'At room temperature (300 K) in an intrinsic semiconductor, how do the hole concentration in the valence band and free electron concentration in the conduction band compare?', '["Holes are much greater than free electrons","Free electrons are much greater than holes","The concentration of positive holes generated in the valence band equals free electrons in the conduction band","Both concentrations are zero"]'::jsonb, 2, 21),
  ('c7e5d7e0-1b4a-4d99-a077-000000000022'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'The time rate of generating electron-hole pairs in an intrinsic semiconductor depends on:', '["Temperature of the semiconductor and type of semiconductor material","Length of connecting wires and battery voltage","Only the mass of the nucleus","Only the reverse bias current"]'::jsonb, 0, 22),
  ('c7e5d7e0-1b4a-4d99-a077-000000000023'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'In an intrinsic semiconductor under an applied electric field, how do positive holes and free electrons move?', '["Both move in the same direction","Holes move in the direction of the electric field while free electrons move in the opposite direction (so holes move opposite to electrons)","Electrons move in the direction of the electric field while holes remain stationary","Neither moves when an electric field is applied"]'::jsonb, 1, 23),
  ('c7e5d7e0-1b4a-4d99-a077-000000000024'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'What is the total current flowing through an intrinsic semiconductor?', '["Only the electron current","Only the hole current","The sum of electron current and hole current (both called charge carriers)","The difference between hole current and electron current"]'::jsonb, 2, 24),
  ('c7e5d7e0-1b4a-4d99-a077-000000000025'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'What is the Fermi level?', '["The lowest energy level inside the core","The highest allowed energy level that an electron can occupy at absolute zero (0 K)","The average of all energy levels in a crystal","The energy level at the top of the valence band in all materials"]'::jsonb, 1, 25),
  ('c7e5d7e0-1b4a-4d99-a077-000000000026'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'In a conductor at 0 K, where does the Fermi level lie?', '["Below all occupied electron levels","Above the region full of electrons in the conduction band","Inside the wide forbidden gap","At the bottom of the valence band"]'::jsonb, 1, 26),
  ('c7e5d7e0-1b4a-4d99-a077-000000000027'::uuid, 'Energy Bands, Intrinsic Semiconductors & Fermi Level', 'Where does the Fermi level lie in an intrinsic semiconductor?', '["Directly on top of the conduction band","In the middle of the forbidden energy gap between conduction band and valence band","Below the valence band","Inside the acceptor level"]'::jsonb, 1, 27),
  ('c7e5d7e0-1b4a-4d99-a077-000000000028'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'Why do we resort to doping with trivalent or pentavalent impurities instead of relying only on thermal effect to control semiconductor conductivity?', '["Because thermal effect does not change conductivity at all","Because controlling electrical conductivity is not possible by thermal effect alone, whereas doping controls it and increases charge carriers significantly","Because doping removes all electrons from the crystal","Because impurities are added at a rate of 1 to 10⁸ to stop current"]'::jsonb, 1, 28),
  ('c7e5d7e0-1b4a-4d99-a077-000000000029'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'How is an N-type semiconductor obtained?', '["By doping an intrinsic semiconductor with trivalent atoms like boron","By carefully and controllably doping an intrinsic semiconductor (Si or Ge) with pentavalent atoms (such as antimony, Sb) at room temperature","By cooling silicon to 0 K","By adding pure copper atoms"]'::jsonb, 1, 29),
  ('c7e5d7e0-1b4a-4d99-a077-000000000030'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'When a pentavalent atom (like antimony) displaces a silicon atom and binds with four neighboring silicon atoms, what happens to its fifth valence electron?', '["It is captured by the nucleus permanently","It is left free in the crystalline structure","It turns into a positive hole in the valence band","It forms a covalent bond with a fifth atom"]'::jsonb, 1, 30),
  ('c7e5d7e0-1b4a-4d99-a077-000000000031'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'Is a donor atom considered a charge carrier?', '["Yes, because it moves freely through the crystal","No, because it does not participate in electrical conductivity; it becomes a positive ion bound strongly with the crystalline structure","Yes, because it carries negative charge through the conduction band","Only at 0 K"]'::jsonb, 1, 31),
  ('c7e5d7e0-1b4a-4d99-a077-000000000032'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'Where is the donor level located, and how does it affect the Fermi level in an N-type semiconductor?', '["Directly above the valence band; Fermi level drops","Within the forbidden energy gap and directly below the conduction band; Fermi level rises close to the conduction band","In the middle of the valence band; Fermi level stays at 0 eV","Above the conduction band; Fermi level disappears"]'::jsonb, 1, 32),
  ('c7e5d7e0-1b4a-4d99-a077-000000000033'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'In an N-type semiconductor at room temperature, what are the majority and minority charge carriers?', '["Holes are majority carriers; electrons are minority carriers","Electrons are majority carriers (from doping and thermal effect); positive holes are minority carriers (generated by thermal effect)","Donor ions are majority carriers; holes are minority carriers","There are no holes in an N-type semiconductor"]'::jsonb, 1, 33),
  ('c7e5d7e0-1b4a-4d99-a077-000000000034'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'What is the net total electrical charge of an N-type semiconductor crystal?', '["Negative","Positive","Zero (electrically neutral), because negative and positive charges are equal in number","Equal to the donor ion charge only"]'::jsonb, 2, 34),
  ('c7e5d7e0-1b4a-4d99-a077-000000000035'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'How is a P-type semiconductor obtained?', '["By doping an intrinsic semiconductor with pentavalent atoms like antimony","By carefully and controllably doping an intrinsic semiconductor (Si or Ge) with trivalent impurities (like boron, B, aluminum, or indium) at room temperature","By removing all holes from germanium","By heating silicon to 1000 K"]'::jsonb, 1, 35),
  ('c7e5d7e0-1b4a-4d99-a077-000000000036'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'Why is a trivalent impurity called an acceptor atom?', '["Because it donates five free electrons to the conduction band","Because each atom of trivalent impurity accepts an electron from the valence electrons to bind four covalent bonds with four silicon atoms","Because it becomes a free positive ion","Because it prevents holes from forming"]'::jsonb, 1, 36),
  ('c7e5d7e0-1b4a-4d99-a077-000000000037'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'Is a negative ion formed by a trivalent acceptor impurity considered a charge carrier?', '["Yes, it moves freely as a negative charge carrier","No, because it binds with the crystalline structure strongly by covalent bonds and does not participate in electrical conductivity","Yes, it is the majority carrier in P-type crystals","Only when reverse biased"]'::jsonb, 1, 37),
  ('c7e5d7e0-1b4a-4d99-a077-000000000038'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'Where is the acceptor level located, and how does it affect the Fermi level in a P- type semiconductor?', '["Directly below the conduction band; Fermi level rises","Within the forbidden energy gap and directly above the valence band; Fermi level drops close to the valence band","Inside the conduction band; Fermi level rises","At the exact center of the gap with no shift"]'::jsonb, 1, 38),
  ('c7e5d7e0-1b4a-4d99-a077-000000000039'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'In a P-type semiconductor, what are the majority and minority charge carriers?', '["Electrons are majority carriers; holes are minority carriers","Positive holes in the valence band are majority carriers; electrons in the conduction band are minority carriers","Acceptor ions are majority carriers; holes are minority carriers","Only electrons conduct current"]'::jsonb, 1, 39),
  ('c7e5d7e0-1b4a-4d99-a077-000000000040'::uuid, 'Extrinsic Semiconductors (N-Type & P-Type)', 'What is the net total charge of a P-type semiconductor crystal?', '["Positive","Negative","Zero (electrically neutral), because negative charges equal positive charges","Equal to the number of holes only"]'::jsonb, 2, 40),
  ('c7e5d7e0-1b4a-4d99-a077-000000000041'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'What are the practical applications of a PN diode in electrical and electronic circuits?', '["Only to store magnetic flux","To control the direction of current and to change or improve output signal shape","Only to amplify audio signals without a battery","To replace all resistors"]'::jsonb, 1, 41),
  ('c7e5d7e0-1b4a-4d99-a077-000000000042'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'How is the depletion region created in a PN diode?', '["Free electrons from N diffuse toward the junction creating positive ions in N, holes move creating negative ions in P, electrons and holes combine near the junction, leaving a thin region devoid of charge carriers","By applying a huge reverse voltage to melt the crystal","By filling the junction with free electrons and holes","By connecting the diode to an AC generator only"]'::jsonb, 0, 42),
  ('c7e5d7e0-1b4a-4d99-a077-000000000043'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'In a PN diode depletion region, which ions are found in the N region and P region?', '["Negative ions in N region and positive ions in P region","Positive ions in N region and negative ions in P region","Only positive ions in both regions","Only negative ions in both regions"]'::jsonb, 1, 43),
  ('c7e5d7e0-1b4a-4d99-a077-000000000044'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'Why does electron diffusion through the PN junction stop at equilibrium?', '["Because the battery turns off automatically","Because positive and negative ions on both sides create an electric field whose potential difference (potential barrier) prevents additional electrons from crossing","Because holes stop existing in the P region","Because temperature reaches absolute zero"]'::jsonb, 1, 44),
  ('c7e5d7e0-1b4a-4d99-a077-000000000045'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'On what factors does the potential barrier in a PN diode depend?', '["Type of semiconductor, rate/percentage of doped impurities, and temperature of the material","Length of the external wire and color of the casing","Only the frequency of the input signal","Only the emitter current"]'::jsonb, 0, 45),
  ('c7e5d7e0-1b4a-4d99-a077-000000000046'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'How is a PN diode connected in the forward bias method?', '["Positive terminal of battery to N region; negative terminal to P region","Positive terminal of battery to P region; negative terminal to N region (with potential difference greater than that on the PN junction)","Both terminals connected to the P region only","Only a single wire connected to the junction"]'::jsonb, 1, 46),
  ('c7e5d7e0-1b4a-4d99-a077-000000000047'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'What happens in a forward-biased PN diode?', '["Depletion region widens and potential barrier increases","Depletion region narrows and potential barrier decreases (applied field opposes and exceeds barrier field), resistance decreases, and a huge forward current flows","Current drops to zero for all voltages","Reverse current becomes dominant"]'::jsonb, 1, 47),
  ('c7e5d7e0-1b4a-4d99-a077-000000000048'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'How is a PN diode connected in the reverse bias method?', '["Positive terminal of battery to P region; negative terminal to N region","Negative terminal of battery to P region; positive terminal to N region","Connected in series with an LED","Connected directly across a 0 K source"]'::jsonb, 1, 48),
  ('c7e5d7e0-1b4a-4d99-a077-000000000049'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'What happens when a PN diode is reversely biased?', '["Depletion region narrows and a huge forward current flows","Electrons in N are attracted to positive terminal and holes in P to negative terminal away from junction; depletion region and potential barrier increase, resistance increases, and only a very small (neglected) reverse current flows","The potential barrier drops to zero","It emits visible light"]'::jsonb, 1, 49),
  ('c7e5d7e0-1b4a-4d99-a077-000000000050'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'When voltage is increased in forward bias, what happens to the forward current? And what happens if polarity is reversed?', '["Forward current decreases; when reversed it becomes huge","Forward current increases; when polarity is reversed (reverse bias), the flowing current through the crystal diode is almost zero","Current stays constant in both cases","Current reverses sign with the same magnitude"]'::jsonb, 1, 50),
  ('c7e5d7e0-1b4a-4d99-a077-000000000051'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'Which of the following are listed types of diodes in Chapter 7?', '["Photosensitive diode, photovoltaic diode (solar cell), light emitting diode (LED), and current rectifier diode","Bipolar transistor, field-effect transistor, and transformer","Photodiode, varactor, and thyristor only","Zener diode and tunnel diode only"]'::jsonb, 0, 51),
  ('c7e5d7e0-1b4a-4d99-a077-000000000052'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'How is a photosensitive diode connected before light falls on it, and what is the current before light is applied?', '["Forward biased; large current flows before light","Reverse biased before applying light; current in the circuit is zero when there is no light effect (thermal current is very weak and neglected)","Unbiased; current is maximum in the dark","Reverse biased; current is independent of light intensity"]'::jsonb, 1, 52),
  ('c7e5d7e0-1b4a-4d99-a077-000000000053'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'What is the purpose of a photosensitive diode, and how does current relate to incident light intensity?', '["Converts electrical energy into light; current is inversely proportional to light intensity","Converts light energy into electrical energy when exposed to light; used in light detectors and light intensity meters; current is directly proportional to incident light intensity","Rectifies AC into DC only","Acts as a temperature sensor only"]'::jsonb, 1, 53),
  ('c7e5d7e0-1b4a-4d99-a077-000000000054'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'For a photovoltaic diode (solar cell), what is the purpose of connecting cells in series versus parallel?', '["Series increases power; parallel increases potential","Series combination increases potential; parallel combination increases power","Both decrease potential and power","Neither changes potential or power"]'::jsonb, 1, 54),
  ('c7e5d7e0-1b4a-4d99-a077-000000000055'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'What photon energy is required to generate an electron-hole pair in silicon and germanium, and what electromotive force (emf) is generated when exposed to incident light?', '["≥ 1.1 eV (emf 0.5 V) for silicon; ≥ 0.72 eV (emf 0.1 V) for germanium","≥ 0.72 eV (emf 0.5 V) for silicon; ≥ 1.1 eV (emf 0.1 V) for germanium","≥ 5.0 eV (emf 5.0 V) for silicon; ≥ 1.1 eV (emf 1.0 V) for germanium","≥ 1.1 eV (emf 0.1 V) for silicon; ≥ 0.72 eV (emf 0.5 V) for germanium"]'::jsonb, 0, 55),
  ('c7e5d7e0-1b4a-4d99-a077-000000000056'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'How is a Light Emitting Diode (LED) connected, and what does it convert?', '["Reverse biased; converts light energy into electrical energy","Forward biased; converts electrical energy into light energy, and is used in digital calculators, clocks, and seven-segment digital screens","Reverse biased; used only in light intensity meters","Forward biased; converts DC into AC"]'::jsonb, 1, 56),
  ('c7e5d7e0-1b4a-4d99-a077-000000000057'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'What do the emitted color and light intensity of an LED depend on?', '["Color depends on the material it is made of (red, yellow, green, or infrared); intensity depends on the amount of flowing forward current (directly proportional)","Color depends on reverse voltage; intensity is inversely proportional to forward current","Both color and intensity depend only on ambient temperature","Color is always green; intensity is constant"]'::jsonb, 0, 57),
  ('c7e5d7e0-1b4a-4d99-a077-000000000058'::uuid, 'PN Junction Diode, Biasing & Special Diodes', 'What happens when an alternating current (AC) passes through a PN current rectifier diode?', '["It amplifies the AC signal without changing shape","It converts AC into a rectified half-wave current: one half-wave (positive polarity) forward-biases the diode and passes current, while the other half-wave reverse-biases it and blocks current","It turns AC into a pure constant battery voltage","It blocks both half-waves completely"]'::jsonb, 1, 58),
  ('c7e5d7e0-1b4a-4d99-a077-000000000059'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'What are the three regions of a transistor, and how are their impurity doping levels ordered?', '["Emitter (high doping), Base (low doping), Collector (medium/average doping)","Emitter (low doping), Base (high doping), Collector (zero doping)","Emitter (medium doping), Base (high doping), Collector (low doping)","All three regions have identical doping"]'::jsonb, 0, 59),
  ('c7e5d7e0-1b4a-4d99-a077-000000000060'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'In a transistor, how are the emitter and collector biased, and why?', '["Emitter is reverse biased; collector is forward biased","Emitter is always forward biased because it supplies charge carriers; collector is reverse biased because it attracts these carriers through the base","Both emitter and collector are always forward biased","Both emitter and collector are always reverse biased"]'::jsonb, 1, 60),
  ('c7e5d7e0-1b4a-4d99-a077-000000000061'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'What are the majority charge carriers performing electrical conduction in a PNP transistor and in an NPN transistor?', '["Electrons in PNP; holes in NPN","Holes move from emitter to collector in PNP; electrons move from emitter to collector in NPN","Only ions in both PNP and NPN","Neither has majority charge carriers"]'::jsonb, 1, 61),
  ('c7e5d7e0-1b4a-4d99-a077-000000000062'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'Why is the base current (IB) very small compared to the emitter current (IE), and why is collector current (IC) never larger than emitter current (IE)?', '["Because the base is wide and heavily doped","Because the base is thin with low impurity doping (allowing maximum carriers to pass from emitter to collector), and recombination at the base gives IC = IE − IB","Because no carriers cross the base","Because IC = IE + IB"]'::jsonb, 1, 62),
  ('c7e5d7e0-1b4a-4d99-a077-000000000063'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'What is the basic function of a transistor, and what does choosing a transistor''s type and shape for a particular application depend on?', '["Rectifying DC; depends on wire color","Amplifying entering signals; depends on input impedance and output impedance","Generating heat; depends on room temperature only","Storing charge like a battery; depends on frequency only"]'::jsonb, 1, 63),
  ('c7e5d7e0-1b4a-4d99-a077-000000000064'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'What are the characteristics of a common-base (grounded-base) PNP amplifier?', '["Small input impedance, very large output impedance, high voltage gain, current gain α = IC / IE less than 1, and output signal in the same phase as input signal","Large input impedance, small output impedance, current gain greater than 100, and 180° phase shift","Zero voltage gain and zero power gain","Output signal 180° out of phase with input signal"]'::jsonb, 0, 64),
  ('c7e5d7e0-1b4a-4d99-a077-000000000065'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'Why can a common-base PNP amplifier not be used for current amplification?', '["Because its voltage gain is zero","Because collector current IC is less than emitter current IE, so current gain α = IC / IE is less than integer 1","Because its input resistance is infinite","Because the emitter-base junction is reverse biased"]'::jsonb, 1, 65),
  ('c7e5d7e0-1b4a-4d99-a077-000000000066'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'In a common-emitter (grounded-emitter) PNP amplifier, why is the output signal out of phase with the input signal (phase difference 180°)?', '["Because collector current changes in the same direction as base current","Because collector current changes in the reverse direction to that of the base current","Because the load resistance is zero","Because the battery is disconnected during positive half-cycles"]'::jsonb, 1, 66),
  ('c7e5d7e0-1b4a-4d99-a077-000000000067'::uuid, 'Transistors, Amplifiers & Numerical Problems', 'In a common-emitter transistor circuit, what are the formulas for current gain (α), voltage gain (AV), and power gain (G)?', '["α = IC / IB, AV = Vout / Vin, and G = α × AV = Pout / Pin","α = IB / IC, AV = Vin / Vout, and G = α + AV","α = IE / IC, AV = IC Rin, and G = AV / α","α = Vout / IB, AV = IE Rout, and G = α − AV"]'::jsonb, 0, 67),
  ('c7e5d7e0-1b4a-4d99-a077-000000000068'::uuid, 'Transistors, Amplifiers & Numerical Problems', '(Ex 1) In a common-base amplifier circuit with IE = 3 mA, IC = 2.94 mA, Rin = 500 Ω, and Rout = 400 kΩ, what are the current gain (α) and voltage gain (AV)?', '["α = 0.98 and AV = 784","α = 1.02 and AV = 784","α = 0.98 and AV = 4500","α = 9 and AV = 784"]'::jsonb, 0, 68),
  ('c7e5d7e0-1b4a-4d99-a077-000000000069'::uuid, 'Transistors, Amplifiers & Numerical Problems', '(Ex 2) In a common-base amplifier with G = 768, AV = 784, and IE = 3 × 10⁻³ A, what is the base current (IB)?', '["2.94 × 10⁻³ A","0.06 × 10⁻³ A (6 × 10⁻⁵ A)","3.06 × 10⁻³ A","0.98 A"]'::jsonb, 1, 69),
  ('c7e5d7e0-1b4a-4d99-a077-000000000070'::uuid, 'Transistors, Amplifiers & Numerical Problems', '(Q9) In a common-emitter circuit with IE = 0.4 mA, IB = 40 μA, Rin = 100 Ω, and Rout = 50 kΩ, calculate α, AV, and G:', '["α = 9, AV = 4500, G = 40500","α = 10, AV = 4500, G = 45000","α = 9, AV = 784, G = 7056","α = 73, AV = 4500, G = 328500"]'::jsonb, 0, 70),
  ('c7e5d7e0-1b4a-4d99-a077-000000000071'::uuid, 'Transistors, Amplifiers & Numerical Problems', '(Q10) In a common-emitter circuit with IB = 50 μA and IC = 3.65 mA, what are α and IE?', '["α = 73 and IE = 370 × 10⁻⁵ A (3.70 mA)","α = 9 and IE = 3.60 mA","α = 73 and IE = 3.60 mA","α = 0.98 and IE = 3.70 mA"]'::jsonb, 0, 71),
  ('c7e5d7e0-1b4a-4d99-a077-000000000072'::uuid, 'Transistors, Amplifiers & Numerical Problems', '(Homework) In a common-emitter circuit with IE = 480 μA, IC = 450 μA, Rin = 20 Ω, and Rout = 80 kΩ, calculate α, AV, and G:', '["IB = 30 μA; α = 15; AV = 60000; G = 900000","IB = 30 μA; α = 15; AV = 6000; G = 90000","IB = 930 μA; α = 15; AV = 60000; G = 900000","IB = 30 μA; α = 0.9375; AV = 60000; G = 56250"]'::jsonb, 0, 72)
)
INSERT INTO public.mcq_banks (id, subject, chapter, chapter_title, section, language, question, choices, answer_index, source, sort_order)
SELECT s.id, 'physics', 7, 'Solid-State Electronics', s.section, 'en', s.question, s.choices, s.answer_index,
       'Chapter 7: Solid-State Electronics - MCQ Bank', s.sort_order
FROM seed s
WHERE NOT EXISTS (
  SELECT 1 FROM public.mcq_banks b
  WHERE b.subject = 'physics' AND b.chapter = 7 AND b.language = 'en' AND b.question = s.question
)
ON CONFLICT (id) DO NOTHING;
